/bin/bash -lc 'for p in about-us/history about-us/governing-body about-us/management-administration centenary-celebrations-srcc disclaimer; do echo "--- $p"; curl -kfsSL --max-time 20 "https://www.srcc.edu/$p" | python3 -c '"'import sys,re,html
from html.parser import HTMLParser
class P(HTMLParser):
 def __init__(self): super().__init__(); self.skip=0; self.out=[]
 def handle_starttag(self,t,a):
  if t in (\"script\",\"style\",\"noscript\"): self.skip+=1
 def handle_endtag(self,t):
  if t in (\"script\",\"style\",\"noscript\") and self.skip: self.skip-=1
 def handle_data(self,d):
  if not self.skip: self.out.append(d)
p=P(); p.feed(sys.stdin.read()); s=html.unescape(\" \".join(p.out)); s=re.sub(r\"\\\\s+\",\" \",s)
for m in re.finditer(r\"["'^.]{0,220}(?:constituent|affiliat|University of Delhi|government college|central university|autonomous|public institution)[''^.]{0,220}",s,re.I): print(m.group(0).strip())'"' | head -30; done"

